k.push(A.eS("panel-assembly","\u0421\u0431\u043e\u0440\u043a\u0430 \u0438 \u0432\u043d\u0443\u0442\u0440\u0435\u043d\u043d\u044f\u044f \u043a\u043e\u043c\u043c\u0443\u0442\u0430\u0446\u0438\u044f \u0449\u0438\u0442\u0430","\u041f\u043e \u0441\u0443\u043c\u043c\u0435 \u0433\u0430\u0431\u0430\u0440\u0438\u0442\u043d\u044b\u0445 \u043c\u043e\u0434\u0443\u043b\u0435\u0439 \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u043d\u043e\u0433\u043e \u043e\u0431\u043e\u0440\u0443\u0434\u043e\u0432\u0430\u043d\u0438\u044f: \u0430\u0432\u0442\u043e\u043c\u0430\u0442 1P \u2014 \u043e\u0431\u044b\u0447\u043d\u043e 1 \u043c\u043e\u0434\u0443\u043b\u044c, \u0423\u0417\u041e 2P \u2014 2; \u0448\u0438\u043d\u044b \u0438 \u0431\u043e\u043a\u0441\u044b \u0432\u043d\u0435 DIN \u2014 \u043f\u043e \u0437\u0430\u0434\u0430\u043d\u043d\u043e\u0439 \u0448\u0438\u0440\u0438\u043d\u0435 \u0432 \u043c\u043e\u0434\u0443\u043b\u044f\u0445. \u0421\u0432\u043e\u0431\u043e\u0434\u043d\u044b\u0435 \u043c\u0435\u0441\u0442\u0430 \u043a\u043e\u0440\u043f\u0443\u0441\u0430 \u043d\u0435 \u0441\u0447\u0438\u0442\u0430\u044e\u0442\u0441\u044f. \u0412\u043a\u043b\u044e\u0447\u0435\u043d\u044b \u0440\u0430\u0437\u043c\u0435\u0449\u0435\u043d\u0438\u0435 \u0430\u043f\u043f\u0430\u0440\u0430\u0442\u043e\u0432 \u0438 \u0448\u0438\u043d, \u0433\u0440\u0435\u0431\u0451\u043d\u043a\u0438, \u0432\u043d\u0443\u0442\u0440\u0435\u043d\u043d\u0438\u0435 \u043f\u0435\u0440\u0435\u043c\u044b\u0447\u043a\u0438 \u0438 \u043c\u0430\u0440\u043a\u0438\u0440\u043e\u0432\u043a\u0430. \u0417\u0430\u043c\u0435\u043d\u044f\u0435\u0442 \u043f\u043e\u0448\u0442\u0443\u0447\u043d\u044b\u0439 \u043c\u043e\u043d\u0442\u0430\u0436 \u0430\u043f\u043f\u0430\u0440\u0430\u0442\u043e\u0432. \u041a\u043e\u0440\u043f\u0443\u0441, \u0432\u043d\u0435\u0448\u043d\u0438\u0435 \u043a\u0430\u0431\u0435\u043b\u0438 \u0438 \u044d\u043b\u0435\u043a\u0442\u0440\u043e\u043b\u0430\u0431\u043e\u0440\u0430\u0442\u043e\u0440\u043d\u044b\u0435 \u0438\u0441\u043f\u044b\u0442\u0430\u043d\u0438\u044f \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e. \u041c\u0438\u043d\u0438\u043c\u0430\u043b\u044c\u043d\u044b\u0439 \u0437\u0430\u043a\u0430\u0437 \u0438 \u0441\u043b\u043e\u0436\u043d\u0430\u044f \u0430\u0432\u0442\u043e\u043c\u0430\u0442\u0438\u043a\u0430 \u0441\u043e\u0433\u043b\u0430\u0441\u0443\u044e\u0442\u0441\u044f \u0441 \u0438\u0441\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u0435\u043c.",B.xf,m,550,300,!1))
